/**
 * Cedar Evaluation Types
 */

export interface Principal {
  role: 'admin' | 'editor' | 'viewer';
  id: string;
}

export interface Resource {
  type: 'document' | 'issue';
  id: string;
  ownerId: string;
  attributes?: {
    isPublic?: boolean;
    isPrivate?: boolean;
    author?: string;
  };
}

export interface EvaluateRequest {
  principal: Principal;
  resource: Resource;
  action: 'read' | 'write' | 'delete';
}

export interface EvaluateResponse {
  decision: 'ALLOW' | 'DENY';
  matchedPolicy?: string;
  reason?: string;
}

export interface ParsedPolicy {
  id: number;
  name: string;
  description: string | null;
  effect: 'permit' | 'deny';
  principalTypes: string[];
  resourceTypes: string[];
  actions: string[];
  condition?: {
    expression: string;
    description: string;
  };
}

/**
 * Error response type
 */
export interface ErrorResponse {
  error: string;
  details?: string;
}

/**
 * Policy Cache Service
 * 
 * Loads and caches all forbid policies at server startup.
 * Cache is refreshed when policies are created/updated/deleted.
 */

import { policyRepository } from '../db/index.js';
import type { Policy, ParsedPolicy } from '../types/index.js';

/**
 * Parse policy from database row to structured format
 */
function parsePolicy(policy: Policy): ParsedPolicy {
  return {
    id: policy.id,
    name: policy.name,
    description: policy.description,
    effect: policy.effect,
    principalTypes: policy.principal_types ? JSON.parse(policy.principal_types) : [],
    resourceTypes: policy.resource_types ? JSON.parse(policy.resource_types) : [],
    actions: policy.actions ? JSON.parse(policy.actions) : [],
    condition: policy.conditions ? JSON.parse(policy.conditions) : undefined
  };
}

/**
 * Policy cache singleton
 */
class PolicyCache {
  private forbidPolicies: ParsedPolicy[] = [];
  private initialized = false;

  /**
   * Load all forbid policies from database
   */
  load(): void {
    const allPolicies = policyRepository.findAll();
    this.forbidPolicies = allPolicies
      .filter(p => p.effect === 'deny')
      .map(parsePolicy);
    this.initialized = true;
    console.log(`[PolicyCache] Loaded ${this.forbidPolicies.length} forbid policies`);
  }

  /**
   * Get all cached forbid policies
   */
  getForbidPolicies(): ParsedPolicy[] {
    return this.forbidPolicies;
  }

  /**
   * Check if cache is initialized
   */
  isInitialized(): boolean {
    return this.initialized;
  }

  /**
   * Refresh cache from database
   */
  refresh(): void {
    this.load();
  }
}

// Export singleton instance
export const policyCache = new PolicyCache();

/**
 * Initialize policy cache at server startup
 */
export function initializePolicyCache(): void {
  policyCache.load();
}

/**
 * Cedar Evaluator Service
 * 
 * Implements Forbid-Only policy evaluation logic.
 * - Forbid exists → DENY
 * - Forbid none → ALLOW
 */

import type { Principal, Resource, EvaluateResponse, ParsedPolicy } from '../types/index.js';
import { policyCache } from './policy-cache.js';

export interface EvaluationContext {
  principal: Principal;
  resource: Resource;
  action: string;
}

/**
 * Check if a role matches a policy's principal types
 */
function matchPrincipal(role: string, policyPrincipalTypes: string[]): boolean {
  if (policyPrincipalTypes.length === 0) return true;
  return policyPrincipalTypes.includes(role);
}

/**
 * Check if a resource type matches a policy's resource types
 */
function matchResourceType(type: string, policyResourceTypes: string[]): boolean {
  if (policyResourceTypes.length === 0) return true;
  return policyResourceTypes.includes(type);
}

/**
 * Check if an action matches a policy's actions
 */
function matchAction(action: string, policyActions: string[]): boolean {
  if (policyActions.length === 0) return true;
  return policyActions.includes(action);
}

/**
 * Evaluate a condition against the request context
 * Returns true if the condition passes (and thus the policy applies)
 */
function evaluateCondition(
  condition: { expression: string; description: string },
  context: EvaluationContext
): boolean {
  // Simple expression evaluation for common patterns
  // Pattern: resource.owner != principal.id
  if (condition.expression.includes('resource.owner') && condition.expression.includes('principal.id')) {
    // Check if resource owner is different from principal
    if (context.resource.ownerId && context.resource.ownerId !== context.principal.id) {
      return true;
    }
    return false;
  }

  // Pattern: resource.isPublic == false
  if (condition.expression.includes('resource.isPublic')) {
    if (context.resource.attributes?.isPublic === false) {
      return true;
    }
    return false;
  }

  // Default: condition is not met
  return false;
}

/**
 * Check if a policy matches the given context
 */
function policyMatches(context: EvaluationContext, policy: ParsedPolicy): { matches: boolean; reason?: string } {
  // Check principal match
  if (!matchPrincipal(context.principal.role, policy.principalTypes)) {
    return { matches: false };
  }

  // Check resource type match
  if (!matchResourceType(context.resource.type, policy.resourceTypes)) {
    return { matches: false };
  }

  // Check action match
  if (!matchAction(context.action, policy.actions)) {
    return { matches: false };
  }

  // Check condition if present
  if (policy.condition) {
    const conditionMet = evaluateCondition(policy.condition, context);
    if (!conditionMet) {
      return { matches: false };
    }
    return { matches: true, reason: policy.condition.description };
  }

  // No condition - policy applies
  return { matches: true, reason: policy.description || `${policy.name} denies this action` };
}

/**
 * Evaluate a request against all forbid policies
 */
export function evaluate(context: EvaluationContext): EvaluateResponse {
  const forbidPolicies = policyCache.getForbidPolicies();

  // Evaluate each forbid policy in order
  for (const policy of forbidPolicies) {
    const result = policyMatches(context, policy);
    if (result.matches) {
      return {
        decision: 'DENY',
        matchedPolicy: policy.name,
        reason: result.reason || `${policy.name}: Principal '${context.principal.role}' is not permitted to ${context.action} '${context.resource.type}' resources`
      };
    }
  }

  // No forbid policy matched → ALLOW
  return {
    decision: 'ALLOW'
  };
}

/**
 * Validate evaluation request
 */
export function validateRequest(request: { principal?: unknown; resource?: unknown; action?: unknown }): string | null {
  if (!request.principal) {
    return 'Missing required field: principal';
  }

  if (!request.resource) {
    return 'Missing required field: resource';
  }

  if (!request.action) {
    return 'Missing required field: action';
  }

  const principal = request.principal as Record<string, unknown>;
  if (!['admin', 'editor', 'viewer'].includes(principal.role as string)) {
    return `Invalid role: ${principal.role}. Must be one of: admin, editor, viewer`;
  }

  if (!principal.id || typeof principal.id !== 'string') {
    return 'Invalid principal.id: must be a non-empty string';
  }

  const resource = request.resource as Record<string, unknown>;
  if (!['document', 'issue'].includes(resource.type as string)) {
    return `Invalid resource type: ${resource.type}. Must be one of: document, issue`;
  }

  if (!resource.id || typeof resource.id !== 'string') {
    return 'Invalid resource.id: must be a non-empty string';
  }

  if (!resource.ownerId || typeof resource.ownerId !== 'string') {
    return 'Invalid resource.ownerId: must be a non-empty string';
  }

  if (!['read', 'write', 'delete'].includes(request.action as string)) {
    return `Invalid action: ${request.action}. Must be one of: read, write, delete`;
  }

  return null;
}

/**
 * Evaluate Route Handler
 * 
 * POST /api/evaluate - Evaluate authorization request
 */

import type { Request, Response } from 'express';
import { evaluate, validateRequest } from '../services/cedar-evaluator.js';
import { policyCache } from '../services/policy-cache.js';
import type { Principal, Resource, EvaluateRequest, ErrorResponse } from '../types/index.js';

/**
 * Handle POST /api/evaluate
 */
export async function handleEvaluate(req: Request, res: Response): Promise<void> {
  try {
    // Validate request
    const validationError = validateRequest(req.body);
    if (validationError) {
      res.status(400).json({ error: 'Bad Request', details: validationError } as ErrorResponse);
      return;
    }

    const { principal, resource, action } = req.body as EvaluateRequest;

    // Ensure policy cache is loaded
    if (!policyCache.isInitialized()) {
      policyCache.refresh();
    }

    // Evaluate the request
    const result = evaluate({
      principal: principal as Principal,
      resource: resource as Resource,
      action
    });

    // Return result
    res.json(result);
  } catch (error) {
    console.error('[Evaluate] Error:', error);
    res.status(500).json({ error: 'Internal Server Error' } as ErrorResponse);
  }
}

/**
 * Register evaluate routes with Express app
 */
export function registerEvaluateRoutes(app: import('express').Express): void {
  app.post('/api/evaluate', handleEvaluate);
  console.log('[Routes] Registered /api/evaluate');
}

/**
 * Cedar Authorization Middleware
 * 
 * Express middleware for Cedar policy evaluation.
 * Can be used to protect routes based on authorization policies.
 */

import type { Request, Response, NextFunction } from 'express';
import { evaluate } from '../services/cedar-evaluator.js';
import { policyCache } from '../services/policy-cache.js';
import type { Principal, Resource, ErrorResponse } from '../types/index.js';

/**
 * Extract principal from request (customize based on auth implementation)
 */
function extractPrincipal(req: Request): Principal | null {
  // For demo purposes, extract from request body or headers
  // In production, this would come from JWT/session
  const body = req.body || {};
  const headers = req.headers || {};

  const role = body.principal?.role || headers['x-user-role'];
  const id = body.principal?.id || headers['x-user-id'];

  if (role && id) {
    return { role, id };
  }

  return null;
}

/**
 * Extract resource from request (customize based on route)
 */
function extractResource(req: Request): Resource | null {
  const body = req.body || {};
  const params = req.params || {};

  const type = body.resource?.type || params.type;
  const id = body.resource?.id || params.id;
  const ownerId = body.resource?.ownerId || params.ownerId;

  if (type && id && ownerId) {
    return {
      type,
      id,
      ownerId,
      attributes: body.resource?.attributes
    };
  }

  return null;
}

/**
 * Extract action from request method or body
 */
function extractAction(req: Request): string | null {
  // Map HTTP methods to actions
  const methodMap: Record<string, string> = {
    GET: 'read',
    POST: 'write',
    PUT: 'write',
    PATCH: 'write',
    DELETE: 'delete'
  };

  const body = req.body || {};
  return body.action || methodMap[req.method] || null;
}

/**
 * Create Cedar authorization middleware
 * 
 * @param options - Middleware configuration
 * @returns Express middleware function
 */
export function cedarMiddleware(options: {
  skipIfNoPrincipal?: boolean;
  onDeny?: (result: { decision: 'DENY'; matchedPolicy?: string; reason?: string }, req: Request) => void;
} = {}) {
  const { skipIfNoPrincipal = true, onDeny } = options;

  return function(req: Request, res: Response, next: NextFunction): void {
    // Ensure policy cache is loaded
    if (!policyCache.isInitialized()) {
      policyCache.refresh();
    }

    const principal = extractPrincipal(req);
    const resource = extractResource(req);
    const action = extractAction(req);

    // Skip if we can't extract required context
    if (!principal) {
      if (skipIfNoPrincipal) {
        next();
        return;
      }
      res.status(401).json({ error: 'Unauthorized: No principal found' } as ErrorResponse);
      return;
    }

    if (!resource) {
      res.status(400).json({ error: 'Bad Request: No resource found' } as ErrorResponse);
      return;
    }

    if (!action) {
      res.status(400).json({ error: 'Bad Request: No action found' } as ErrorResponse);
      return;
    }

    // Evaluate authorization
    const result = evaluate({ principal, resource, action });

    if (result.decision === 'DENY') {
      if (onDeny) {
        onDeny(result, req);
      }
      res.status(403).json({
        error: 'Forbidden',
        details: result.reason,
        matchedPolicy: result.matchedPolicy
      } as ErrorResponse & { matchedPolicy?: string });
      return;
    }

    // ALLOW - continue to route handler
    next();
  };
}

/**
 * Pre-configured middleware for protected routes
 */
export const requireAuthorization = cedarMiddleware({
  skipIfNoPrincipal: false
});

/**
 * Optional authorization middleware (continues if no principal)
 */
export const optionalAuthorization = cedarMiddleware({
  skipIfNoPrincipal: true
});

